{"op":"add","path":"/root","value":"wizard"}
{"op":"add","path":"/elements/wizard","value":{"type":"Stack","props":{"direction":"vertical","gap":"lg"},"children":["intro","step-indicator","panel-account","panel-prefs","panel-done"]}}
{"op":"add","path":"/elements/intro","value":{"type":"Stack","props":{"direction":"vertical","gap":"sm"},"children":["intro-heading","intro-text"]}}
{"op":"add","path":"/elements/intro-heading","value":{"type":"Heading","props":{"text":"Create your account","level":"h2"},"children":[]}}
{"op":"add","path":"/elements/intro-text","value":{"type":"Text","props":{"text":"Three quick steps to get you started. You can go back at any time.","variant":"muted"},"children":[]}}
{"op":"add","path":"/elements/step-indicator","value":{"type":"Stack","props":{"direction":"horizontal","gap":"sm","align":"center"},"children":["badge-account","badge-prefs","badge-done"]}}
{"op":"add","path":"/elements/badge-account","value":{"type":"Badge","props":{"text":"1. Account","variant":{"$cond":{"$state":"/currentStep","eq":"account"},"$then":"default","$else":"outline"}},"children":[]}}
{"op":"add","path":"/elements/badge-prefs","value":{"type":"Badge","props":{"text":"2. Preferences","variant":{"$cond":{"$state":"/currentStep","eq":"preferences"},"$then":"default","$else":"outline"}},"children":[]}}
{"op":"add","path":"/elements/badge-done","value":{"type":"Badge","props":{"text":"3. Done","variant":{"$cond":{"$state":"/currentStep","eq":"done"},"$then":"default","$else":"outline"}},"children":[]}}
{"op":"add","path":"/elements/panel-account","value":{"type":"Card","props":{"title":"Step 1 of 3 — Account details"},"visible":{"$state":"/currentStep","eq":"account"},"children":["acct-form"]}}
{"op":"add","path":"/elements/acct-form","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"children":["input-name","input-email","input-password","acct-actions"]}}
{"op":"add","path":"/elements/input-name","value":{"type":"Input","props":{"label":"Full name","placeholder":"Ada Lovelace","value":{"$bindState":"/form/fullName"}},"children":[]}}
{"op":"add","path":"/elements/input-email","value":{"type":"Input","props":{"label":"Work email","type":"email","placeholder":"ada@company.com","value":{"$bindState":"/form/email"}},"children":[]}}
{"op":"add","path":"/elements/input-password","value":{"type":"Input","props":{"label":"Password","type":"password","placeholder":"At least 8 characters","value":{"$bindState":"/form/password"}},"children":[]}}
{"op":"add","path":"/elements/acct-actions","value":{"type":"Stack","props":{"direction":"horizontal","gap":"sm","align":"end"},"children":["acct-next"]}}
{"op":"add","path":"/elements/acct-next","value":{"type":"Button","props":{"label":"Next","variant":"default"},"on":{"press":{"action":"setState","params":{"statePath":"/currentStep","value":"preferences"}}},"children":[]}}
{"op":"add","path":"/elements/panel-prefs","value":{"type":"Card","props":{"title":"Step 2 of 3 — Preferences"},"visible":{"$state":"/currentStep","eq":"preferences"},"children":["prefs-form"]}}
{"op":"add","path":"/elements/prefs-form","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"children":["pref-theme","pref-lang","pref-notifications","pref-newsletter","prefs-actions"]}}
{"op":"add","path":"/elements/pref-theme","value":{"type":"Select","props":{"label":"Appearance","options":["Light","Dark","System default"],"value":{"$bindState":"/form/theme"}},"children":[]}}
{"op":"add","path":"/elements/pref-lang","value":{"type":"Select","props":{"label":"Language","options":["English","Spanish","French","German","Japanese"],"value":{"$bindState":"/form/language"}},"children":[]}}
{"op":"add","path":"/elements/pref-notifications","value":{"type":"Switch","props":{"label":"Email notifications","description":"Product updates, security alerts, and mentions.","checked":{"$bindState":"/form/notifications"}},"children":[]}}
{"op":"add","path":"/elements/pref-newsletter","value":{"type":"Checkbox","props":{"label":"Send me the weekly digest newsletter","checked":{"$bindState":"/form/newsletter"}},"children":[]}}
{"op":"add","path":"/elements/prefs-actions","value":{"type":"Stack","props":{"direction":"horizontal","gap":"sm","align":"end"},"children":["prefs-back","prefs-next"]}}
{"op":"add","path":"/elements/prefs-back","value":{"type":"Button","props":{"label":"Back","variant":"secondary"},"on":{"press":{"action":"setState","params":{"statePath":"/currentStep","value":"account"}}},"children":[]}}
{"op":"add","path":"/elements/prefs-next","value":{"type":"Button","props":{"label":"Finish setup","variant":"default"},"on":{"press":{"action":"setState","params":{"statePath":"/currentStep","value":"done"}}},"children":[]}}
{"op":"add","path":"/elements/panel-done","value":{"type":"Card","props":{"title":"Step 3 of 3 — You're all set"},"visible":{"$state":"/currentStep","eq":"done"},"children":["done-body"]}}
{"op":"add","path":"/elements/done-body","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"children":["done-alert","done-summary","done-actions"]}}
{"op":"add","path":"/elements/done-alert","value":{"type":"Alert","props":{"title":"Account created successfully","description":"We sent a verification link to your email. Click it to confirm your address before inviting teammates."},"children":[]}}
{"op":"add","path":"/elements/done-summary","value":{"type":"Text","props":{"text":{"$template":"Welcome, ${/form/fullName}! Your workspace is set to ${/form/theme} appearance with ${/form/language} as your language. Email notifications are ${/form/notifications}."},"variant":"body"},"children":[]}}
{"op":"add","path":"/elements/done-actions","value":{"type":"Stack","props":{"direction":"horizontal","gap":"sm","align":"end"},"children":["done-back","done-launch"]}}
{"op":"add","path":"/elements/done-back","value":{"type":"Button","props":{"label":"Back to preferences","variant":"ghost"},"on":{"press":{"action":"setState","params":{"statePath":"/currentStep","value":"preferences"}}},"children":[]}}
{"op":"add","path":"/elements/done-launch","value":{"type":"Button","props":{"label":"Go to dashboard","variant":"default"},"on":{"press":{"action":"setState","params":{"statePath":"/launched","value":true}}},"children":[]}}
{"op":"add","path":"/state/currentStep","value":"account"}
{"op":"add","path":"/state/launched","value":false}
{"op":"add","path":"/state/form/fullName","value":"Ada Lovelace"}
{"op":"add","path":"/state/form/email","value":"ada@analytical.co"}
{"op":"add","path":"/state/form/password","value":""}
{"op":"add","path":"/state/form/theme","value":"System default"}
{"op":"add","path":"/state/form/language","value":"English"}
{"op":"add","path":"/state/form/notifications","value":true}
{"op":"add","path":"/state/form/newsletter","value":false}
